<?php require __DIR__.'/includes/bootstrap.php';$q=trim((string)get('q',''));$products=[];$suggest=[];if($q!==''){ $term='%'.$q.'%';$st=db()->prepare("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.status=1 AND (p.name LIKE ? OR p.sku LIKE ? OR p.description LIKE ? OR p.brand LIKE ?) ORDER BY p.featured DESC LIMIT 60");$st->execute([$term,$term,$term,$term]);$products=$st->fetchAll();}$title='Search';require __DIR__.'/includes/header.php';?>
